import React, { useEffect, useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import AOS from "aos";

import img1 from "./assests/dates.jpg";
import img2 from "./assests/nuts.jpg";
import img3 from "./assests/seeds.jpg";

export default function HerbsSpicesHome() {
  const slides = [
    {
      image: img1,
      title: "Fresh Dates",
      offer: "FLAT 10% OFF",
      coupon: "DATE10",
    },
    {
      image: img2,
      title: "Premium Nuts",
      offer: "BUY 1 GET 1 FREE",
      coupon: "NUTS50",
    },
    {
      image: img3,
      title: "Organic Seeds",
      offer: "20% OFF",
      coupon: "SEED20",
    },
  ];

  const [index, setIndex] = useState(0);

  // Auto slider
  useEffect(() => {
    AOS.init({ duration: 1000 });
    const timer = setInterval(() => {
      setIndex((prev) => (prev + 1) % slides.length);
    }, 4000);

    return () => clearInterval(timer);
  }, []);

  const goPrev = () => {
    setIndex((prev) => (prev - 1 + slides.length) % slides.length);
  };

  const goNext = () => {
    setIndex((prev) => (prev + 1) % slides.length);
  };

  return (
    <div className="position-relative w-100 vh-100 overflow-hidden">

      {/* Background Slider */}
      <div
        className="position-absolute top-0 start-0 w-100 h-100"
        style={{
          backgroundImage: `url(${slides[index].image})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          transition: "background-image 1s ease-in-out",
        }}
      ></div>

      {/* Dark Overlay */}
      <div className="position-absolute top-0 start-0 w-100 h-100 bg-dark opacity-50"></div>

      {/* Navbar */}
      <nav className="navbar navbar-expand-lg navbar-dark bg-dark bg-opacity-75 position-fixed top-0 w-100 py-2 shadow">
        <div className="container-fluid px-4">
          <a className="navbar-brand fs-2 fw-bold text-warning" href="#">
            ✺ Sinthu
          </a>

          <button
            className="navbar-toggler"
            type="button"
            data-bs-toggle="collapse"
            data-bs-target="#navMenu"
          >
            <span className="navbar-toggler-icon"></span>
          </button>

          <div className="collapse navbar-collapse" id="navMenu">
            <ul className="navbar-nav mx-auto mb-2 mb-lg-0 gap-3 fs-5 fw-semibold">
              <li className="nav-item"><a className="nav-link" href="#">Home</a></li>
              <li className="nav-item"><a className="nav-link" href="#">Shop</a></li>
              <li className="nav-item"><a className="nav-link" href="#">Dates</a></li>
              <li className="nav-item"><a className="nav-link" href="#">Nuts</a></li>
              <li className="nav-item"><a className="nav-link" href="#">Seeds</a></li>
              <li className="nav-item"><a className="nav-link" href="#">Pages</a></li>
            </ul>

            <div className="d-flex align-items-center gap-4 fs-4 text-white">
              <i className="ri-search-line"></i>
              <span className="fs-6">USD ▾</span>
              <i className="ri-shopping-cart-line"></i>
              <i className="ri-user-line"></i>
            </div>
          </div>
        </div>
      </nav>

      {/* Dynamic Overlay Text */}
      <div
        className="position-relative text-center text-white d-flex flex-column justify-content-center align-items-center h-100 px-3"
        data-aos="fade-up"
        key={index}
      >
        <h1 className="display-1 fw-bold text-shadow">{slides[index].title}</h1>
        <p className="fs-2 fw-semibold mt-3">{slides[index].offer}</p>
        <p className="fs-5 mt-2">
          USE COUPON :{" "}
          <span className="fw-bold text-warning">{slides[index].coupon}</span>
        </p>
      </div>

      {/* Left Arrow */}
      <button
        onClick={goPrev}
        className="btn btn-dark bg-opacity-75 position-absolute top-50 start-0 translate-middle-y rounded-circle p-3 fs-3"
      >
        ❮
      </button>

      {/* Right Arrow */}
      <button
        onClick={goNext}
        className="btn btn-dark bg-opacity-75 position-absolute top-50 end-0 translate-middle-y rounded-circle p-3 fs-3"
      >
        ❯
      </button>
    </div>
  );
}
